-- GENERATED by tests/mk.py. Rolled back by its own last statement (RESULT: ...). Changes nothing.
begin;
-- security_nov22: shared guard, included at the top of every migration here (01-04). Safe to run many times.
-- pb_sec.guard(tag, function, md5): refuses (and so rolls the whole migration back) when the live definition of a
-- function we replace is not the one read on Nov 21 2026. When it matches, the live definition is saved first in
-- pb_sec.fn_backup, so the undo files put back the exact text that was live (no copy typed by hand).
-- Running a migration a second time: the backup row is already there, so it goes through again.
create schema if not exists pb_sec;
revoke all on schema pb_sec from public;
revoke all on schema pb_sec from anon, authenticated;
create table if not exists pb_sec.fn_backup (
  tag      text not null,          -- which migration (nov22_01 ...)
  sig      text not null,          -- regprocedure text, e.g. public.pb_session_gate()
  def      text not null,          -- pg_get_functiondef() as it was live
  md5      text not null,
  saved_at timestamptz not null default now(),
  primary key (tag, sig)
);
alter table pb_sec.fn_backup enable row level security;
revoke all on table pb_sec.fn_backup from public;
revoke all on table pb_sec.fn_backup from anon, authenticated;

create or replace function pb_sec.guard(p_tag text, p_sig text, p_md5 text) returns void
language plpgsql set search_path = '' as $f$
declare v_def text; v_md5 text;
begin
  v_def := pg_get_functiondef(p_sig::regprocedure);
  v_md5 := md5(v_def);
  if v_md5 = p_md5 then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  if exists (select 1 from pb_sec.fn_backup b where b.tag = p_tag and b.sig = p_sig) then return; end if; -- this migration ran before
  -- (throwaway local test database only: the stand-in functions there are not the live text)
  if current_setting('pb_sec.guard', true) = 'skip-local-test' then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  raise exception 'pb_sec: % changed on live since Nov 21 2026 (md5 % , expected %). Nothing was applied. Re-read it and rebase this migration.', p_sig, v_md5, p_md5;
end $f$;
revoke all on function pb_sec.guard(text, text, text) from public;
revoke all on function pb_sec.guard(text, text, text) from anon, authenticated;

-- undo helper: puts back every function a migration replaced, exactly as it was live
create or replace function pb_sec.restore(p_tag text) returns integer
language plpgsql set search_path = '' as $f$
declare r record; n integer := 0;
begin
  for r in select b.sig, b.def from pb_sec.fn_backup b where b.tag = p_tag order by b.sig loop
    execute r.def; n := n + 1;
  end loop;
  delete from pb_sec.fn_backup where tag = p_tag;
  return n;
end $f$;
revoke all on function pb_sec.restore(text) from public;
revoke all on function pb_sec.restore(text) from anon, authenticated;

-- security_nov22 02 (review finding 2, MEDIUM): a removed crew member can no longer add versions to the company's records.
-- Before:
--   public.pb_permit_backup(text, jsonb, uuid) (the 4-argument one the app calls ends here too) found the permit by
--   (user, client id) only, so someone removed from the company kept adding versions to a permit filed under it; and
--   closed_at = coalesce(new lockTime, closed_at) let any later version move a permit's close time.
--   public.pb_run_seal_add() filed a new sealed run PDF for any run record of the caller, whatever company they are in now.
-- After:
--   permit backup: a permit filed under a company takes new versions only from someone still in that company (a member
--   row for it, or its owner; company status is not checked, so a closed or unpaid company never blocks a crew's permit
--   backups). Refused: 'pb:not_company_member' (the app keeps the permit on the phone and tries again later; nothing is
--   lost). Personal permits (no company) are unchanged. A re-send of the exact version already filed still answers
--   ok/same, so a removed member's queue clears. closed_at, once set, never moves.
--   OPTION (default OFF): pb_safety.closed_frozen() = true refuses any new, different version once a permit is closed
--   ('pb:permit_closed'). Turn on only with 02b_freeze_closed_on.sql, and only after the app words that code (see NOTES).
--   seal add: the run record's company must be the caller's company now (pb_prod.my_company, like
--   pb_prod_run_record_put). Refused: 'pb:not_company_member'.
-- Run as postgres, in one transaction (the whole file). Safe to run twice. Undo: undo/99_undo_02.sql.

select pb_sec.guard('nov22_02', 'public.pb_permit_backup(text,jsonb,uuid)', '20eacb984a31e485eb21f3d8075d4923');
select pb_sec.guard('nov22_02', 'public.pb_run_seal_add(text,text,text,integer,text,timestamp with time zone,text)', 'dcb126dc18d5aba070a8991742f8d5f4');

-- the freeze switch (decision for Tommy). false = as today: a closed permit still takes later versions.
-- Created only if missing, so running this file again never turns a freeze back off.
do $d$ begin
  if to_regprocedure('pb_safety.closed_frozen()') is null then
    execute $x$create function pb_safety.closed_frozen() returns boolean language sql immutable set search_path = '' as 'select false'$x$;
    execute 'revoke all on function pb_safety.closed_frozen() from public';
    execute 'revoke all on function pb_safety.closed_frozen() from anon, authenticated';
  end if;
end $d$;

CREATE OR REPLACE FUNCTION public.pb_permit_backup(p_client_permit_id text, p_record jsonb, p_expect_uid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_permit pb_safety.permits%rowtype;
  v_sha text;
  v_last text;
  v_closed timestamptz;
  v_size integer;
  v_new_today integer;
  v_bytes bigint;
begin
  if v_uid is null then raise exception 'pb:signed_out'; end if;
  if p_expect_uid is null or v_uid <> p_expect_uid then raise exception 'pb:wrong_account'; end if;
  if p_client_permit_id is null or length(p_client_permit_id) not between 1 and 100 then raise exception 'pb:bad_id'; end if;
  if p_record is null or jsonb_typeof(p_record) <> 'object' or coalesce(p_record->>'kind', '') <> 'confined' then raise exception 'pb:bad_record'; end if;
  v_size := pg_column_size(p_record);
  if v_size > 2000000 then raise exception 'pb:too_big'; end if;
  v_sha := encode(sha256(convert_to(p_record::text, 'UTF8')), 'hex');
  begin v_closed := (p_record->>'lockTime')::timestamptz; exception when others then v_closed := null; end;
  select * into v_permit from pb_safety.permits where user_id = v_uid and client_permit_id = p_client_permit_id;
  if not found then
    select count(*) into v_new_today from pb_safety.permits where user_id = v_uid and first_backed_up_at > now() - interval '1 day';
    if v_new_today >= 300 then raise exception 'pb:quota'; end if;
    select m.company_id into v_company from public.company_members m
      where m.user_id = v_uid and (m.created_at is null or m.created_at <= coalesce(v_closed, now()))
      order by m.created_at desc nulls last limit 1;
    insert into pb_safety.permits (user_id, company_id, client_permit_id, space, jobsite, job_number, closed_at)
      values (v_uid, v_company, p_client_permit_id, left(p_record->>'space', 300), left(p_record->>'jobsite', 300), left(p_record->>'jobNumber', 100), v_closed)
      on conflict (user_id, client_permit_id) do nothing;
  end if;
  select * into v_permit from pb_safety.permits where user_id = v_uid and client_permit_id = p_client_permit_id for update;
  select pv.record_sha256 into v_last from pb_safety.permit_versions pv where pv.permit_id = v_permit.id order by pv.version desc limit 1;
  if v_last = v_sha then
    return jsonb_build_object('ok', true, 'same', true, 'version', v_permit.version_count);
  end if;
  -- security_nov22 02: a company's permit takes new versions only from someone still in that company (member or owner)
  if v_permit.company_id is not null
     and not exists (select 1 from public.company_members m where m.user_id = v_uid and m.company_id = v_permit.company_id)
     and not exists (select 1 from public.companies c where c.id = v_permit.company_id and c.owner_user_id = v_uid) then
    raise exception 'pb:not_company_member';
  end if;
  -- security_nov22 02 (option, off unless pb_safety.closed_frozen() says true): a closed permit takes no new versions
  if v_permit.closed_at is not null and v_last is not null and pb_safety.closed_frozen() then
    raise exception 'pb:permit_closed';
  end if;
  if v_permit.version_count >= 500 then raise exception 'pb:too_many_versions'; end if;
  select coalesce(sum(p.bytes_total), 0) into v_bytes from pb_safety.permits p where p.user_id = v_uid;
  if v_bytes + v_size > 200000000 then raise exception 'pb:quota'; end if;
  insert into pb_safety.permit_versions (permit_id, version, record, record_sha256)
    values (v_permit.id, v_permit.version_count + 1, p_record, v_sha);
  update pb_safety.permits set version_count = v_permit.version_count + 1, last_backed_up_at = now(), bytes_total = bytes_total + v_size,
    space = left(p_record->>'space', 300), jobsite = left(p_record->>'jobsite', 300), job_number = left(p_record->>'jobNumber', 100),
    closed_at = coalesce(closed_at, v_closed) -- security_nov22 02: once set, the close time never moves (was coalesce(v_closed, closed_at))
    where id = v_permit.id;
  return jsonb_build_object('ok', true, 'same', false, 'version', v_permit.version_count + 1);
end $function$;

CREATE OR REPLACE FUNCTION public.pb_run_seal_add(p_entry_id text, p_path text, p_sha256 text, p_bytes integer, p_key text, p_made_at timestamp with time zone, p_build text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_company uuid; v_safe text; v_size bigint; v_have pb_prod.run_seals; v_n int;
begin
  if v_uid is null then raise exception 'pb:signed_out'; end if;
  v_safe := regexp_replace(coalesce(p_entry_id, ''), '[^A-Za-z0-9_.-]', '_', 'g');
  if p_path is null or p_path !~ ('^' || v_uid::text || '/runs/' || replace(v_safe, '.', '\.') || '/[0-9]{8}T[0-9]{6}-' || left(coalesce(p_sha256, ''), 16) || '\.pdf$') then raise exception 'pb:bad_path'; end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'pb:bad_sha'; end if;
  select r.company_id into v_company from pb_prod.run_records r where r.user_id = v_uid and r.entry_id = p_entry_id;
  if not found then raise exception 'pb:no_run'; end if;
  select (o.metadata->>'size')::bigint into v_size from storage.objects o where o.bucket_id = 'run-seals' and o.name = p_path and o.owner_id = v_uid::text;
  if not found then raise exception 'pb:no_file'; end if;
  if v_size is distinct from p_bytes::bigint then raise exception 'pb:size_mismatch'; end if;
  select * into v_have from pb_prod.run_seals s where s.path = p_path;
  if found then return jsonb_build_object('ok', true, 'version', v_have.version, 'sealed_at', v_have.sealed_at, 'again', true); end if;
  -- security_nov22 02: a new seal only while the caller is still in the run record's company (as pb_prod_run_record_put);
  -- one already filed still answers 'again' above, so a removed member's queue clears
  if v_company is distinct from pb_prod.my_company(v_uid) then raise exception 'pb:not_company_member'; end if;
  select count(*) into v_n from pb_prod.run_seals s where s.user_id = v_uid and s.entry_id = p_entry_id;
  if v_n >= 50 then raise exception 'pb:too_many'; end if;
  insert into pb_prod.run_seals (user_id, company_id, entry_id, version, path, sha256, bytes, seal_key, app_build, made_at)
  values (v_uid, v_company, p_entry_id, v_n + 1, p_path, p_sha256, p_bytes, left(p_key, 80), left(p_build, 60), p_made_at)
  returning * into v_have;
  return jsonb_build_object('ok', true, 'version', v_have.version, 'sealed_at', v_have.sealed_at);
end $function$;

-- security_nov22 02 test: removed members and company permits / sealed runs. Ends with 'RESULT: ...' (rolled back).
create function pg_temp.s2_as(p_user uuid) returns void language sql as $f$
  select set_config('request.jwt.claims', jsonb_build_object('role', 'authenticated', 'sub', p_user, 'aal', 'aal1')::text, true); $f$;
create function pg_temp.s2_bk(p_user uuid, p_cid text, p_rec jsonb) returns text language plpgsql as $f$
declare j jsonb;
begin perform pg_temp.s2_as(p_user); j := public.pb_permit_backup(p_cid, p_rec, p_user);
  return case when (j->>'same')::boolean then 'same' else 'v' || (j->>'version') end;
exception when others then return 'ERR ' || sqlerrm; end $f$;
create function pg_temp.s2_rec(p_n integer, p_lock text default null) returns jsonb language sql as $f$
  select jsonb_strip_nulls(jsonb_build_object('kind', 'confined', 'space', 'MH-12', 'jobsite', 'Test', 'jobNumber', 'J1', 'n', p_n, 'lockTime', p_lock)) $f$;
create function pg_temp.s2_seal(p_user uuid, p_entry text, p_path text, p_sha text) returns text language plpgsql as $f$
declare j jsonb;
begin perform pg_temp.s2_as(p_user); j := public.pb_run_seal_add(p_entry, p_path, p_sha, 1000, 'k', now(), 'test');
  return 'v' || (j->>'version') || case when (j->>'again')::boolean then ' again' else '' end;
exception when others then return 'ERR ' || sqlerrm; end $f$;

do $test$
declare
  pass integer; fail integer; fails text; notes text := ''; tag text := substr(md5(random()::text), 1, 10);
  o uuid := gen_random_uuid(); m uuid := gen_random_uuid(); m2 uuid := gen_random_uuid(); solo uuid := gen_random_uuid(); o2 uuid := gen_random_uuid();
  c uuid := gen_random_uuid(); c2 uuid := gen_random_uuid(); x text; t1 timestamptz := now() - interval '3 hours'; t2 timestamptz := now() - interval '1 hour';
  sha text; path text; sha2 text; path2 text; seal_ok boolean := true;
begin
  create temp table t_chk (i serial, name text, ok boolean, got text) on commit drop;
  insert into auth.users (id, email) select v, 'pbsec02-' || tag || '-' || row_number() over () || '@example.invalid' from unnest(array[o, m, m2, solo, o2]) v;
  insert into public.companies (id, name, owner_user_id, status, plan) values (c, 'pbsec02 ' || tag, o, 'active', 'trial'), (c2, 'pbsec02b ' || tag, o2, 'active', 'trial');
  insert into public.company_members (company_id, user_id, role, created_at) values (c, m, 'foreman', now() - interval '1 day'), (c, m2, 'foreman', now() - interval '1 day');

  -- ===== permits =====
  x := pg_temp.s2_bk(m, 'p1-' || tag, pg_temp.s2_rec(1));
  insert into t_chk (name, ok, got) select '2a member files a permit (v1) under the company', x = 'v1' and (select company_id from pb_safety.permits where user_id = m and client_permit_id = 'p1-' || tag) = c, x;
  x := pg_temp.s2_bk(m, 'p1-' || tag, pg_temp.s2_rec(2));
  insert into t_chk (name, ok, got) values ('2b member adds v2', x = 'v2', x);
  delete from public.company_members where user_id = m and company_id = c;   -- removed from the company
  x := pg_temp.s2_bk(m, 'p1-' || tag, pg_temp.s2_rec(3));
  insert into t_chk (name, ok, got) values ('2c removed member: new version refused', x = 'ERR pb:not_company_member', x);
  insert into t_chk (name, ok, got) select '2d nothing was added', (select version_count from pb_safety.permits where user_id = m and client_permit_id = 'p1-' || tag) = 2, '';
  x := pg_temp.s2_bk(m, 'p1-' || tag, pg_temp.s2_rec(2));
  insert into t_chk (name, ok, got) values ('2e removed member re-sending the filed version: ok/same (queue clears)', x = 'same', x);
  insert into public.company_members (company_id, user_id, role) values (c2, m, 'foreman');
  x := pg_temp.s2_bk(m, 'p1-' || tag, pg_temp.s2_rec(4));
  insert into t_chk (name, ok, got) values ('2f now in another company: still refused for the old company''s permit', x = 'ERR pb:not_company_member', x);
  x := pg_temp.s2_bk(m, 'p9-' || tag, pg_temp.s2_rec(1));
  insert into t_chk (name, ok, got) select '2g a new permit files under the new company', x = 'v1' and (select company_id from pb_safety.permits where user_id = m and client_permit_id = 'p9-' || tag) = c2, x;
  -- owner of the company (owners are not member rows)
  insert into pb_safety.permits (user_id, company_id, client_permit_id) values (o, c, 'po-' || tag);
  x := pg_temp.s2_bk(o, 'po-' || tag, pg_temp.s2_rec(1));
  insert into t_chk (name, ok, got) values ('2h the company owner may add versions to a permit filed under it', x = 'v1', x);
  -- a closed or unpaid company never blocks the crew's backups
  update public.companies set status = 'inactive' where id = c;
  x := pg_temp.s2_bk(m2, 'p2-' || tag, pg_temp.s2_rec(1, t1::text));
  insert into t_chk (name, ok, got) values ('2i member of an inactive company: still backs up', x = 'v1', x);
  update public.companies set status = 'active' where id = c;
  -- closed_at never moves
  x := pg_temp.s2_bk(m2, 'p2-' || tag, pg_temp.s2_rec(2, t2::text));
  insert into t_chk (name, ok, got) select '2j a later version with another close time: filed, close time kept',
    x = 'v2' and (select closed_at from pb_safety.permits where user_id = m2 and client_permit_id = 'p2-' || tag) = t1, x;
  x := pg_temp.s2_bk(m2, 'p2-' || tag, pg_temp.s2_rec(3));
  insert into t_chk (name, ok, got) select '2k a version without a close time: close time kept',
    x = 'v3' and (select closed_at from pb_safety.permits where user_id = m2 and client_permit_id = 'p2-' || tag) = t1, x;
  -- personal permits
  x := pg_temp.s2_bk(solo, 'ps-' || tag, pg_temp.s2_rec(1)) || '/' || pg_temp.s2_bk(solo, 'ps-' || tag, pg_temp.s2_rec(2));
  insert into t_chk (name, ok, got) values ('2l someone with no company: personal permit unchanged', x = 'v1/v2', x);
  -- the freeze option
  insert into t_chk (name, ok, got) values ('2m freeze switch is OFF by default', not pb_safety.closed_frozen(), '');
  create or replace function pb_safety.closed_frozen() returns boolean language sql immutable set search_path = '' as 'select true';
  x := pg_temp.s2_bk(m2, 'p2-' || tag, pg_temp.s2_rec(4, t1::text));
  insert into t_chk (name, ok, got) values ('2n freeze ON: a closed permit refuses a new version', x = 'ERR pb:permit_closed', x);
  x := pg_temp.s2_bk(m2, 'p2-' || tag, pg_temp.s2_rec(3));
  insert into t_chk (name, ok, got) values ('2o freeze ON: re-sending the filed version still ok/same', x = 'same', x);
  x := pg_temp.s2_bk(m2, 'p3-' || tag, pg_temp.s2_rec(1, t1::text)) || '/' || pg_temp.s2_bk(m2, 'p4-' || tag, pg_temp.s2_rec(1)) || '/' || pg_temp.s2_bk(m2, 'p4-' || tag, pg_temp.s2_rec(2));
  insert into t_chk (name, ok, got) values ('2p freeze ON: first (closed) version files; open permits unaffected', x = 'v1/v1/v2', x);
  create or replace function pb_safety.closed_frozen() returns boolean language sql immutable set search_path = '' as 'select false';
  -- the app's 4-argument call ends in the 3-argument one (live only)
  if to_regprocedure('public.pb_permit_backup(text,jsonb,uuid,text)') is not null then
    perform pg_temp.s2_as(m);
    begin perform public.pb_permit_backup('p1-' || tag, pg_temp.s2_rec(5), m, null); x := 'filed';
    exception when others then x := sqlerrm; end;
    insert into t_chk (name, ok, got) values ('2q the app''s 4-argument call is refused the same way', x = 'pb:not_company_member', x);
  end if;

  -- ===== sealed run PDFs =====
  delete from public.company_members where user_id = m and company_id = c2;
  insert into public.company_members (company_id, user_id, role) values (c, m, 'foreman'); -- back in c for the seal part
  sha := encode(extensions.digest('a' || tag, 'sha256'), 'hex'); path := m::text || '/runs/r1-' || tag || '/20261121T101010-' || left(sha, 16) || '.pdf';
  sha2 := encode(extensions.digest('b' || tag, 'sha256'), 'hex'); path2 := m::text || '/runs/r1-' || tag || '/20261121T111111-' || left(sha2, 16) || '.pdf';
  insert into pb_prod.run_records (company_id, user_id, entry_id, record, record_md5) values (c, m, 'r1-' || tag, '{}', '');
  begin
    insert into storage.objects (bucket_id, name, owner_id, metadata) values ('run-seals', path, m::text, '{"size": 1000}'), ('run-seals', path2, m::text, '{"size": 1000}');
  exception when others then seal_ok := false; notes := notes || ' [seal checks skipped: storage.objects not writable here: ' || sqlerrm || ']'; end;
  if seal_ok then
    x := pg_temp.s2_seal(m, 'r1-' || tag, path, sha);
    insert into t_chk (name, ok, got) values ('2r member seals a run PDF', x = 'v1', x);
    delete from public.company_members where user_id = m and company_id = c;
    x := pg_temp.s2_seal(m, 'r1-' || tag, path2, sha2);
    insert into t_chk (name, ok, got) values ('2s removed member: a new seal is refused', x = 'ERR pb:not_company_member', x);
    x := pg_temp.s2_seal(m, 'r1-' || tag, path, sha);
    insert into t_chk (name, ok, got) values ('2t removed member re-sending the filed seal: again (queue clears)', x = 'v1 again', x);
    insert into public.company_members (company_id, user_id, role) values (c2, m, 'foreman');
    x := pg_temp.s2_seal(m, 'r1-' || tag, path2, sha2);
    insert into t_chk (name, ok, got) values ('2u in another company now: still refused for the old company''s run', x = 'ERR pb:not_company_member', x);
  end if;

  insert into t_chk (name, ok, got) select '2v both live functions saved for undo', (select count(*) from pb_sec.fn_backup where fn_backup.tag = 'nov22_02') = 2, '';
  -- undo: the old permit backup takes the removed member's version again
  perform pb_sec.restore('nov22_02');
  delete from public.company_members where user_id = m;
  x := pg_temp.s2_bk(m, 'p1-' || tag, pg_temp.s2_rec(6));
  insert into t_chk (name, ok, got) values ('2w undo (restore) brings back the old function', coalesce(x, '(local stand-in)') <> 'ERR pb:not_company_member', x);

  select count(*) filter (where ok), count(*) filter (where ok is not true), coalesce(string_agg(name || ' [got: ' || coalesce(got, 'null') || ']', ' ; ' order by i) filter (where ok is not true), '') into pass, fail, fails from t_chk;
  raise exception 'RESULT: % pass, % fail% %', pass, fail, case when fail > 0 then ' | FAILED: ' || fails else '' end, notes;
end $test$;

rollback;
